+     * Must be a subset of {@link BlockBenchmark#RELEVANT_TYPE_BLOCK_COMBINATIONS}
+     */
+    @Param(
+        {
+            "boolean/array",
+            "boolean/array-multivalue-null",
+            "boolean/big-array",
+            "boolean/big-array-multivalue-null",
