+        }
+
+        @Override
+        public void onComplete() {
+            finishTask();
+            if (downstream != null) {
+                downstream.onComplete();
+            }
+        }
+
+        private void finishTask() {
+            if (isClosed.compareAndSet(false, true) && task != null) {
+                taskManager.unregister(task);
+            }
+        }
+    }
+}

