+                try {
+                    // publish a second message
+                    publisher.consumeContent(contentDecoder(message), mock(IOControl.class));
+                    super.requestData();
+                    // and then exit out of the loop
+                    publisher.cancel();
+                } catch (IOException e) {
+                    throw new RuntimeException(e);
+                }
+                super.onNext(item);
+            }
+        };
+        publisher.subscribe(subscriber);
