+                            foundAttributes.add(fieldAttribute);
+                            changedAggregates = true;
+                            orderedAggregates.add(as.replaceChild(af.withDocValues()));
+                        } else {
+                            orderedAggregates.add(aggExpr);
+                        }
+                    } else {
+                        orderedAggregates.add(aggExpr);
+                    }
