+                    exec = new AggregateExec(
+                        agg.source(),
+                        agg.child(),
+                        agg.groupings(),
+                        orderedAggregates,
+                        agg.getMode(),
+                        agg.intermediateAttributes(),
+                        agg.estimatedRowSize()
+                    );
+                }
+            }
