+        long totalSizeInBytes = merge.totalBytesSize();
+        currentMerges.inc();
+        currentMergesNumDocs.inc(totalNumDocs);
+        currentMergesSizeInBytes.inc(totalSizeInBytes);
+        onGoingMerges.add(onGoingMerge);
+
