+            totalMergesSizeInBytes.count(),
+            currentMerges.count(),
+            currentMergesNumDocs.count(),
+            currentMergesSizeInBytes.count(),
+            totalMergeStoppedTime.count(),
+            totalMergeThrottledTime.count(),
